"""Self-hosted browser QA of comic speech, original audio, and both OBS layouts."""
from pathlib import Path
from http.server import ThreadingHTTPServer,SimpleHTTPRequestHandler
from threading import Thread
from playwright.sync_api import sync_playwright
import json,shutil
OUT=Path('docs/comic-qa');OUT.mkdir(exist_ok=True)
class Handler(SimpleHTTPRequestHandler):
 def __init__(self,*args,**kw):super().__init__(*args,directory='dist',**kw)
 def log_message(self,*args):pass
server=ThreadingHTTPServer(('127.0.0.1',0),Handler);Thread(target=server.serve_forever,daemon=True).start();url=f'http://127.0.0.1:{server.server_port}'
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=shutil.which('chromium'),headless=True,args=['--no-sandbox','--autoplay-policy=no-user-gesture-required']);page=b.new_page(viewport={'width':1600,'height':1000});errors=[];failed=[]
 page.on('pageerror',lambda e:errors.append(str(e)));page.on('response',lambda r:failed.append([r.status,r.url]) if r.status>=400 else None)
 page.add_init_script('''window.__comicTexts=[];window.__bannerDraws=[];window.__speech=[];const ft=CanvasRenderingContext2D.prototype.fillText;CanvasRenderingContext2D.prototype.fillText=function(t,...a){if(this.font.includes('Times New Roman'))window.__comicTexts.push({text:t,font:this.font});return ft.call(this,t,...a)};const di=CanvasRenderingContext2D.prototype.drawImage;CanvasRenderingContext2D.prototype.drawImage=function(im,...a){if(im?.src?.includes('_dialogue'))window.__bannerDraws.push(im.src);return di.call(this,im,...a)};const start=AudioBufferSourceNode.prototype.start;AudioBufferSourceNode.prototype.start=function(...a){if(this.buffer?.duration>1&&this.buffer.duration<10)window.__speech.push({duration:this.buffer.duration,offset:a[1]||0});return start.apply(this,a)};''')
 page.goto(url,wait_until='networkidle');page.evaluate('async()=>await window.arena.ready');page.click('#chooseBattle');page.select_option('#pick0','ichigo');page.select_option('#pick1','gojo');page.evaluate('async()=>await window.arena.ready');page.click('#start');page.wait_for_function('window.arena.simulation.tick>2');page.click('#start')
 page.evaluate("()=>{const d=window.arena.simulation;for(const f of d.fighters){f.rage=0;f.think=999;f.state='idle';}d.fighters[0].rage=100;}");page.click('#start');page.wait_for_function("window.arena.simulation.personalUltimate.cinematic?.kind==='fullgetsuga'");page.wait_for_timeout(450);page.locator('#game').screenshot(path=str(OUT/'ichigo.png'));page.click('#start');elapsed=page.evaluate('window.arena.simulation.personalUltimate.cinematic.elapsed');page.wait_for_timeout(250);assert page.evaluate('window.arena.simulation.personalUltimate.cinematic.elapsed')==elapsed;page.click('#start');page.wait_for_function("window.arena.simulation.personalUltimate.attack?.phase==='warning'");page.click('#start')
 voice=page.evaluate('window.__speech');assert sum(abs(v['duration']-3.04)<.01 for v in voice)>=2 and any(abs(v['duration']-3.04)<.01 and v['offset']>.2 for v in voice),voice
 page.select_option('#mode','teams');page.select_option('#teamPickA0','sukuna');page.evaluate('async()=>await window.arena.ready');page.click('#start');page.wait_for_function('window.arena.simulation.tick>2');page.click('#start');page.evaluate("()=>{const d=window.arena.simulation;for(const f of d.fighters){f.rage=0;f.think=999;f.state='idle';}d.fighters[0].damage=999;d.teamUltimate.teams.A.rage=100;}");page.click('#start');page.wait_for_function('window.arena.simulation.teamUltimate.cinematic');page.wait_for_timeout(450);page.locator('#game').screenshot(path=str(OUT/'team-sukuna.png'));assert page.evaluate('window.__bannerDraws.length')==0;normaltexts=page.evaluate('window.__comicTexts');assert any('everything' in t['text'] for t in normaltexts);assert any('Domain' in t['text'] for t in normaltexts)
 for mode in ['vote','vertical']:
  page.set_viewport_size({'width':1080,'height':1920});page.goto(url+'/?obs='+mode,wait_until='networkidle');page.wait_for_function('window.arena?.simulation.tick>2',timeout=60000);page.keyboard.press('Space');page.evaluate("()=>{const d=window.arena.simulation;d.personalUltimate.cinematic=d.personalUltimate.attack=null;if(d.teamUltimate)d.teamUltimate.cinematic=d.teamUltimate.attack=null;for(const f of d.fighters){f.rage=0;f.state='idle';f.think=999;}d.fighters[0].rage=100;}");page.keyboard.press('Space');page.wait_for_function('window.arena.simulation.personalUltimate.cinematic');page.wait_for_timeout(400);page.locator('#portraitGame').screenshot(path=str(OUT/(mode+'.png')));assert page.evaluate('window.__bannerDraws.length')==0;assert page.evaluate('window.__comicTexts.length')>0
 assert not errors and not failed,(errors,failed)
 result={'checks':['Ichigo personal comic speech','Sukuna team comic speech','native isolated actor, no banner draw calls','Times New Roman font requests and wrapped text','original voice decoded, pause/resume offset','unchanged cinematic ticks while paused','Full HD vote and vertical presentations'],'voiceSources':voice,'pageErrors':errors,'failedResponses':failed,'subjectiveListening':False};(OUT/'results.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result));b.close()
server.shutdown()
